/**
 * この関数は、[0 .. 15]の範囲の疑似乱数整数を出力します。
 *
 * @param s     tinymtの内部状態へのポインター。
 * @return      0以上15以下の符号なし整数。
 */
uint32_t tinymt32_rand16(tinymt32_t *s)
{
    return (tinymt32_generate_uint32(s) & 0xF);
}

/**
 * この関数は、[0 .. 255]の範囲の疑似乱数整数を出力します。
 *
 * @param s     tinymtの内部状態へのポインター。
 * @return      0以上255以下の符号なし整数。
 */
uint32_t tinymt32_rand256(tinymt32_t *s)
{
    return (tinymt32_generate_uint32(s) & 0xFF);
}

#include <string.h>

/*
 * 指定された修復シンボルのキーに対して使用する適切な数の符号化
 * 係数で、渡された（正しいサイズの）符号化係数のテーブルを埋めます。
 *
 * (in) repair_key    この修復シンボルに関連付けられたキー。m=1かつ
 *                    dt=15の場合、このパラメーターは無視されます
 *                    （不要です）。
 * (in/out) cc_tab    符号化係数を格納するための、正しいサイズの
 *                    テーブルへのポインター。この関数から戻った
 *                    時点で、すべての係数は、mパラメーターに
 *                    かかわらずバイトとして格納されています。
 * (in) cc_nb         cc_tabテーブルのエントリー数。この値は、
 *                    現在の符号化ウィンドウのサイズに等しいです。
 * (in) dt            密度を制御する0から15まで（両端を含む）の
 *                    整数。値が15の場合、すべての係数が0でない
 *                    ことが保証されます（つまり、GF(2)では1に
 *                    等しく、GF(2^^8)では{1,... 255}の値に
 *                    等しくなります）。それ以外の場合は、その
 *                    一部が0になります。
 * (in) m             有限体GF(2^^m)のパラメーター。この文書では
 *                    値1と8のみを考慮します。
 * (out)              成功した場合は0を返し、それ以外の場合は0と
 *                    異なるエラーコードを返します。
 */
int generate_coding_coefficients (uint16_t  repair_key,
                                  uint8_t*  cc_tab,
                                  uint16_t  cc_nb,
                                  uint8_t   dt,
                                  uint8_t   m)
{
    uint32_t      i;
    tinymt32_t    s;    /* PRNGの内部状態 */

    if (dt > 15) {
        return -1; /* エラー、不正なdtパラメーター */
    }
    switch (m) {
    case 1:
        if (dt == 15) {
            /* すべての係数は1 */
            memset(cc_tab, 1, cc_nb);
        } else {
            /* ここでは係数は0または1のいずれか */
            tinymt32_init(&s, repair_key);
            for (i = 0 ; i < cc_nb ; i++) {
                cc_tab[i] = (tinymt32_rand16(&s) <= dt) ? 1 : 0;
            }
        }
        break;

    case 8:
        tinymt32_init(&s, repair_key);
        if (dt == 15) {
            /* すべてのソースシンボルを含めるために、ここでは
             * 係数0を避ける */
            for (i = 0 ; i < cc_nb ; i++) {
                do {
                    cc_tab[i] = (uint8_t) tinymt32_rand256(&s);
                } while (cc_tab[i] == 0);
            }
        } else {
            /* ここでは一定数の係数が0になるはず */
            for (i = 0 ; i < cc_nb ; i++) {
                if (tinymt32_rand16(&s) <= dt) {
                    do {
                        cc_tab[i] = (uint8_t) tinymt32_rand256(&s);
                    } while (cc_tab[i] == 0);
                } else {
                    cc_tab[i] = 0;
                }
            }
        }
        break;

    default:
        return -2; /* エラー、不正なパラメーターm */
    }
    return 0; /* 成功 */
}
